using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class DiagnoseLioraExpressionShading {
 const string Output="Data/Liora/ShadingRepair/Diagnosis/";
 static Mesh Snapshot(SkinnedMeshRenderer r,Transform root){
 var source=r.sharedMesh;var p=source.vertices;var n=source.normals;var t=source.tangents;var dp=new Vector3[p.Length];var dn=new Vector3[p.Length];var dt=new Vector3[p.Length];
 for(int s=0;s<source.blendShapeCount;s++){float w=r.GetBlendShapeWeight(s)*.01f;if(w==0)continue;source.GetBlendShapeFrameVertices(s,0,dp,dn,dt);for(int j=0;j<p.Length;j++){p[j]+=dp[j]*w;n[j]+=dn[j]*w;if(t.Length>0)t[j]+=new Vector4(dt[j].x,dt[j].y,dt[j].z,0)*w;}}
 var matrices=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*source.bindposes[j]).ToArray();var normalMatrices=matrices.Select(m=>m.inverse.transpose).ToArray();var op=new Vector3[p.Length];var on=new Vector3[p.Length];var ot=new Vector4[p.Length];
 using(var counts=source.GetBonesPerVertex())using(var weights=source.GetAllBoneWeights()){int at=0;for(int j=0;j<p.Length;j++){Vector3 tangent=Vector3.zero;for(int k=0;k<counts[j];k++){var w=weights[at++];op[j]+=matrices[w.boneIndex].MultiplyPoint3x4(p[j])*w.weight;on[j]+=normalMatrices[w.boneIndex].MultiplyVector(n[j])*w.weight;if(t.Length>0)tangent+=matrices[w.boneIndex].MultiplyVector(t[j])*w.weight;}on[j].Normalize();tangent.Normalize();if(t.Length>0)ot[j]=new Vector4(tangent.x,tangent.y,tangent.z,t[j].w);}}
 var m=new Mesh{name="Evaluated shading diagnosis",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};m.vertices=op;m.normals=on;if(t.Length>0)m.tangents=ot;m.uv=source.uv;m.subMeshCount=source.subMeshCount;for(int j=0;j<source.subMeshCount;j++)m.SetTriangles(source.GetTriangles(j),j);m.RecalculateBounds();return m;
 }
 static void PoseNormals(Mesh mesh,Mesh neutral,JToken sections){
 var p=mesh.vertices;var p0=neutral.vertices;var n=mesh.normals;var t=mesh.tangents;var n0=neutral.normals;var t0=neutral.tangents;
 foreach(var section in sections.Where(s=>((string)s["name"]).StartsWith("BAKED_head_lod0_mesh"))){int start=(int)section["offset"],count=(int)section["vertices"];var tris=Enumerable.Range((int)section["firstSubmesh"],(int)section["submeshes"]).SelectMany(mesh.GetTriangles).Select(j=>j-start).ToArray();if(tris.Any(j=>j<0||j>=count))throw new Exception("Section topology mismatch");var work=new Mesh{vertices=p0.Skip(start).Take(count).ToArray(),triangles=tris};try{work.RecalculateNormals();var g0=work.normals;work.vertices=p.Skip(start).Take(count).ToArray();work.RecalculateNormals();var g1=work.normals;for(int j=0;j<count;j++){int i=start+j;var q=Quaternion.FromToRotation(g0[j],g1[j]);n[i]=q*n0[i];Vector3 v=q*(Vector3)t0[i];t[i]=new Vector4(v.x,v.y,v.z,t0[i].w);}}finally{UnityEngine.Object.DestroyImmediate(work);}}
 mesh.normals=n;mesh.tangents=t;
 }
 public static object Run(){
 if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");Directory.CreateDirectory(Output);var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Liora/Candidate/Liora_Candidate.prefab");var scene=EditorSceneManager.NewPreviewScene();Mesh neutral=null;
 try{var face=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single(r=>r.name=="Face");var sections=JObject.Parse(File.ReadAllText("Data/Liora/HierarchyRepair/sections.json"))["sections"];for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);neutral=Snapshot(face,root.transform);
 var cg=new GameObject("Shading comparison camera");SceneManager.MoveGameObjectToScene(cg,scene);var camera=cg.AddComponent<Camera>();camera.scene=scene;camera.cameraType=CameraType.Preview;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.13f,.15f,.18f);camera.orthographic=true;camera.orthographicSize=.16f;camera.nearClipPlane=.01f;camera.farClipPlane=10;camera.transform.position=new Vector3(0,1.61f,3);camera.transform.LookAt(new Vector3(0,1.61f,0));
 foreach(var pair in new[]{(rotation:new Vector3(25,155,0),intensity:1.5f),(rotation:new Vector3(-15,215,0),intensity:.8f)}){var go=new GameObject("Diagnosis light");SceneManager.MoveGameObjectToScene(go,scene);var l=go.AddComponent<Light>();l.type=LightType.Directional;l.intensity=pair.intensity;l.shadows=LightShadows.None;l.cullingMask=1<<30;go.transform.rotation=Quaternion.Euler(pair.rotation);}
 var files=new List<string>();foreach(string pose in new[]{"Neutral","Joy","BlinkLeft","BlinkRight","SpeechFF"}){
 for(int s=0;s<face.sharedMesh.blendShapeCount;s++)face.SetBlendShapeWeight(s,0);string shape=pose=="Joy"?"emo_joy":pose=="BlinkLeft"?"eyeBlinkLeft":pose=="BlinkRight"?"eyeBlinkRight":pose=="SpeechFF"?"viseme_FF":null;if(shape!=null)face.SetBlendShapeWeight(face.sharedMesh.GetBlendShapeIndex(shape),100);
 foreach(string variant in new[]{"Original","NoNormalMap","UnlitSkin","SkinOnly","PoseNormals"}){
 var mesh=Snapshot(face,root.transform);var materials=face.sharedMaterials.Select(m=>new Material(m)).ToArray();var go=new GameObject("Explicit evaluated face");SceneManager.MoveGameObjectToScene(go,scene);go.layer=30;go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;
 try{
 var skin=sections.Where(s=>((string)s["name"]).StartsWith("BAKED_head_lod0_mesh")).ToArray();
 if(variant=="NoNormalMap")foreach(var m in materials){if(m.HasProperty("_BumpMap"))m.SetTexture("_BumpMap",null);m.DisableKeyword("_NORMALMAP");}
 if(variant=="UnlitSkin")foreach(var section in skin)for(int s=(int)section["firstSubmesh"];s<(int)section["firstSubmesh"]+(int)section["submeshes"];s++){var old=materials[s];var m=new Material(Shader.Find("Universal Render Pipeline/Unlit"));m.SetTexture("_BaseMap",old.GetTexture("_BaseMap"));m.SetColor("_BaseColor",old.GetColor("_BaseColor"));UnityEngine.Object.DestroyImmediate(old);materials[s]=m;}
 if(variant=="SkinOnly"){var keep=new HashSet<int>(skin.SelectMany(s=>Enumerable.Range((int)s["firstSubmesh"],(int)s["submeshes"])));for(int s=0;s<mesh.subMeshCount;s++)if(!keep.Contains(s))mesh.SetTriangles(Array.Empty<int>(),s);}
 if(variant=="PoseNormals")PoseNormals(mesh,neutral,sections);
 renderer.sharedMaterials=materials;var rt=RenderTexture.GetTemporary(640,720,24);var previous=RenderTexture.active;try{camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;var tex=new Texture2D(640,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,640,720),0,0);tex.Apply();string file=Output+pose+"_"+variant+".png";File.WriteAllBytes(file,tex.EncodeToPNG());files.Add(file);UnityEngine.Object.DestroyImmediate(tex);}finally{camera.targetTexture=null;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
 }finally{UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(mesh);foreach(var m in materials)UnityEngine.Object.DestroyImmediate(m);}
 }}var report=new{files,poses=5,variants=5,normalTexturesAndMaterialsNotEdited=true,shadowsDisabledForAllDiagnosticVariants=true,skinSectionsFromCurrentManifest=true,sceneSaved=false};File.WriteAllText("Data/Liora/ShadingRepair/diagnosis.json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{images=files.Count};
 }finally{if(neutral)UnityEngine.Object.DestroyImmediate(neutral);PrefabUtility.UnloadPrefabContents(root);EditorSceneManager.ClosePreviewScene(scene);}
 }
}
